from dataclasses import dataclass
from adaptix import Retort, name_mapping, NameStyle, ExtraForbid, DebugTrail
@dataclass
class M:
    first_name: int
    second: int = 0
r = Retort(recipe=[name_mapping(M, aliases={'first_name': 'old'}, extra_in=ExtraForbid())], debug_trail=DebugTrail.FIRST)
assert r.load({'old': 1}, M) == M(1)
assert r.dump(M(1)) == {'first_name': 1, 'second': 0}
r = Retort(recipe=[name_mapping(M, aliases={'first_name':'new'}), name_mapping(M, aliases={'first_name':'old', 'second':'legacy'})])
assert r.load({'new': 1, 'legacy': 2}, M) == M(1, 2)
for aliases in ({'first_name':'first_name'}, {'first_name':'second'}, {'first_name':'same','second':'same'}):
    try: Retort(recipe=[name_mapping(M, aliases=aliases)]).get_loader(M)
    except Exception: pass
    else: raise AssertionError(aliases)
print('focused alias checks passed')
